def filter_dataframes(dataframes):
    filtered = {}
    for name, df in dataframes.items():
        df_copy = df.copy()
        if name == 'sales_pipeline.csv' and 'channel' in df_copy.columns:
            df_copy = df_copy[df_copy['channel'].str.lower() != 'partner']
        filtered[name] = df_copy
    return filtered
